param(
 [Parameter(Mandatory=$true)]
 [string]$ProcessName
)

$proc = Get-Process -Name $ProcessName -ErrorAction SilentlyContinue
if (-not $proc) {
 Write-Output "Process '$ProcessName' not found."
 exit
}

$cpuInfo = Get-CimInstance Win32_Processor
$logicalCount = [Environment]::ProcessorCount
$physicalCores = ($cpuInfo.NumberOfCores)
$totalLogical = ($cpuInfo.NumberOfLogicalProcessors)

$mask = 0
for ($i = 0; $i -lt $totalLogical; $i++) {
 if ($i -lt $physicalCores) {
 $mask = $mask -bor (1 -shl $i)
 }
}

$proc.ProcessorAffinity = $mask
Write-Output "Process '$ProcessName' now runs only on P-Cores ($physicalCores cores)."
